=== Method: calc (AbstractMethod) ===
/* used to decide whether rollot should be enabled and be ready to  get trigger*/
/*******************************************************************************/
/* Basically rollout should be enabled in case								   */
/* - PrepareHold request is received
   - vehicle speed is reduced from a speed more than a minimum limit (rollout intended 
   to be the reduction of speed in uphill scenario from a certain speed level to 0)
/**************************************************************************/

// Veheicle deceleration estimated based on slope and act prop force
if(VehMovDirGear == CSMVehMovDir_Undefined)
{
	CsmAVehRolloutEstimated = -ASlopeInSelMovDir;
}
else
{
	CsmAVehRolloutEstimated = -ASlopeInSelMovDir + APropAct;
}

if(VehStop == true){	tVehStopped = (tVehStopped + CycleTime).min(C_CSM_RolloutAvoidInStop + CycleTime);
}else{	tVehStopped = 0;
}

// Enable rollout in case
if(
		VVehComfort			<  C_CSM_RolloutVMax			// define a maximum speed to avoid overbraked vehicle
	// Function need to define use case like slope 	&&	tVehStopped			<= C_CSM_RolloutAvoidInStop
	&&	CsmHoldRolloutReq	!= CSMRolloutReq_Off			// Rollout is enabled by feature
	&&	(	CsmHoldStandbyReqActive					>  0					// Standy Services are requested
		||	CsmHoldBrkHoldReqActive					>  0					// Brake Hold is requested
		||	(	CsmHoldDriveOffReqActive				>  0					// Drive Off is requested
			&&	CsmHoldDriveOffEnableReactByBrkInc 	== true))
)
{
	CsmRolloutEnabled = true;
// In case rollout already triggered maintain it active as long as it's not canceled by the requester
}else if(
		CsmRolloutActive	== true					// and alreaady active
	&&	CsmHoldRolloutReq	!= CSMRolloutReq_Off			// Rollout is enabled by feature
	&&	(	CsmHoldStandbyReqActive					>  0					// Standy Services are requested
		||	CsmHoldBrkHoldReqActive					>  0					// Brake Hold is requested
		||	(	CsmHoldDriveOffReqActive				>  0					// Drive Off is requested
			&&	CsmHoldDriveOffEnableReactByBrkInc 	== true))
)
{
	CsmRolloutEnabled = true;
}else
{
	CsmRolloutEnabled = false;
}



// Estimation of actual vehicle deceleration
// Weighted between (weighted because the estimated deceleration is only relevant in case so far no measured deceleration is seen)
//    - the measured vehicle deceleration (out of wheel speed info)
//    - and the estimated vehicle deceleration calcualted out of current slope and actual prop force
// Estimation about expected vehicle deceleration, dertermined by available propulsive force and estimated slope
CsmAVehRolloutForTrigger = AVeh.min(((CsmAVehRolloutEstimated + C_CSM_RolloutDecelByAPropOffset)*C_CSM_RolloutWeightAProp.getAt(AVeh)*C_CSM_RolloutWeightAPropSpeed.getAt(VVehComfort)));

// Estimation of actual free rolling vehicle deceleration (2Steps)
// 1. Take the measured deceleration and compensate it with current brake force
//	  In case the compensation leads to less no visible deceleration anymore the value is
//	  limited to maximum between the measured deceleration and the estimated vehicle deceleration 
CsmAVehRollout = (AVeh + ABrkSys.abs()).min((CsmAVehRolloutEstimated).max(AVeh));
// 2. In case there is so far no measured deceleration seen at at all again wight against the estimated deceleration
// Estimation about expected vehicle deceleration only by rollout of vehicle (compensate applied brake pressure)
CsmAVehRollout = CsmAVehRollout.min((CsmAVehRolloutEstimated*C_CSM_RolloutWeightAProp.getAt(AVeh)*C_CSM_RolloutWeightAPropSpeed.getAt(VVehComfort)));


=== Method: CsmAVehRollout (AbstractMethod) ===
return CsmAVehRollout;


=== Method: CsmAVehRolloutForTrigger (AbstractMethod) ===
return CsmAVehRolloutForTrigger;


=== Method: CsmRolloutEnabled (AbstractMethod) ===
return CsmRolloutEnabled;
